<script>
const specimen = document.querySelector('#specimen');
const size = document.querySelector('#fontSize');
const leading = document.querySelector('#leading');
const sizeOut = document.querySelector('#sizeOut');
const leadingOut = document.querySelector('#leadingOut');
const density = document.querySelector('#density');
const densityBar = document.querySelector('#densityBar');
const columns = document.querySelector('#columns');
const verdict = document.querySelector('#verdict');
const fontToggle = document.querySelector('#fontToggle');

function tune() {
    const px = Number(size.value);
    const line = Number(leading.value) / 100;
    specimen.style.fontSize = px + 'px';
    specimen.style.lineHeight = line;
    sizeOut.value = px + 'px';
    leadingOut.value = line.toFixed(2);
    const col = Math.max(30, Math.round(1320 / px));
    const dense = Math.max(35, Math.min(99, Math.round(116 - px * 1.9)));
    columns.textContent = col;
    density.textContent = dense;
    densityBar.style.width = dense + '%';
    verdict.textContent = px <= 13
        ? 'Brave. Efficient. Possibly a cry for help. Check those commas twice.'
        : px >= 24
            ? 'Luxurious glyph acreage. Lovely for demos; expensive in split panes.'
            : 'Comfortably compact. Plenty of log line before the wrap gremlin arrives.';
}
size.addEventListener('input', tune);
leading.addEventListener('input', tune);
fontToggle.addEventListener('click', () => {
    const on = fontToggle.getAttribute('aria-pressed') === 'true';
    fontToggle.setAttribute('aria-pressed', String(!on));
    fontToggle.textContent = on ? 'System mono engaged' : 'Iosevka engaged';
    specimen.style.fontFamily = on ? 'monospace' : '"Iosevka Lab", monospace';
});
tune();

const tests = [
    { text: 'AO0X', index: 2, choices: ['zero', 'capital O'], answer: 'zero' },
    { text: 'fl1I', index: 2, choices: ['one', 'lowercase l'], answer: 'one' },
    { text: 'Il1I', index: 1, choices: ['lowercase l', 'capital I'], answer: 'lowercase l' },
    { text: 'S5$S', index: 1, choices: ['five', 'capital S'], answer: 'five' },
    { text: 'qg9q', index: 2, choices: ['nine', 'lowercase g'], answer: 'nine' },
    { text: 'OQ0O', index: 1, choices: ['capital Q', 'zero'], answer: 'capital Q' },
    { text: 'B8BB', index: 1, choices: ['eight', 'capital B'], answer: 'eight' }
];
let deck = [], current = null, gameRound = 0, score = 0, startedAt = 0;
const target = document.querySelector('#target');
const answers = document.querySelector('#answers');
const roundOut = document.querySelector('#round');
const scoreOut = document.querySelector('#gameScore');
const timerOut = document.querySelector('#timer');
const gameMessage = document.querySelector('#gameMessage');
const stamp = document.querySelector('#stamp');

function shuffle(items) {
    return [...items].sort(() => Math.random() - .5);
}
function nextRound() {
    if (gameRound === 5) return finishGame();
    current = deck[gameRound];
    gameRound++;
    roundOut.textContent = gameRound;
    target.innerHTML = [...current.text].map((c, i) => i === current.index ? `<u>${c}</u>` : c).join('');
    answers.innerHTML = '';
    shuffle(current.choices).forEach(choice => {
        const button = document.createElement('button');
        button.className = 'answer';
        button.textContent = choice;
        button.addEventListener('click', () => answer(choice));
        answers.appendChild(button);
    });
}
function answer(choice) {
    const correct = choice === current.answer;
    if (correct) score++;
    scoreOut.textContent = score;
    gameMessage.textContent = correct ? 'Confirmed. Clean identification.' : `Negative. That was ${current.answer}.`;
    [...answers.children].forEach(button => button.disabled = true);
    setTimeout(nextRound, 650);
}
function startGame() {
    deck = shuffle(tests).slice(0, 5);
    gameRound = 0;
    score = 0;
    startedAt = performance.now();
    scoreOut.textContent = '0';
    stamp.classList.remove('show');
    gameMessage.textContent = 'Inspection underway…';
    nextRound();
}
function finishGame() {
    const seconds = ((performance.now() - startedAt) / 1000).toFixed(1);
    timerOut.textContent = seconds + 's';
    target.textContent = `${score}/5`;
    answers.innerHTML = '<button class="start-game" id="retry">Run it again</button>';
    document.querySelector('#retry').addEventListener('click', startGame);
    gameMessage.textContent = score === 5 ? 'No impostors escaped. Sharp eyes.' : score >= 3 ? 'Operationally sound. Keep one eye on the lowercase l.' : 'Recommend larger type and one strong coffee.';
    stamp.textContent = score === 5 ? 'Cleared' : 'Retest';
    stamp.classList.add('show');
}
document.querySelector('#startGame').addEventListener('click', startGame);

const observer = new IntersectionObserver(entries => {
    entries.forEach(entry => {
        if (entry.isIntersecting) {
            entry.target.classList.add('visible');
            observer.unobserve(entry.target);
        }
    });
}, { threshold: .12 });
document.querySelectorAll('.reveal').forEach(el => observer.observe(el));
</script>
</body>
</html>
